import type { Lesson, LessonCheck, TrackId } from "~/content/curriculum";

type Spec = Omit<Lesson, "id" | "number" | "track"> & {
  checks: LessonCheck[];
};
const make = (track: TrackId, specs: Spec[]): Lesson[] =>
  specs.map((lesson, index) => ({
    ...lesson,
    id: `${track}-${index + 3}`,
    number: index + 3,
    track,
  }));

